#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int grid[10][10];
    int zero_r = -1, zero_c = -1;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &grid[i][j]);
            if (grid[i][j] == 0) {
                zero_r = i;
                zero_c = j;
            }
        }
    }

    int full_row = (zero_r == 0) ? 1 : 0;
    int target_sum = 0;
    for (int j = 0; j < n; j++) {
        target_sum += grid[full_row][j];
    }

    int current_sum = 0;
    for (int j = 0; j < n; j++) {
        current_sum += grid[zero_r][j];
    }

    int missing_value = target_sum - current_sum;

    printf("%d\n", missing_value);
    printf("%d\n", zero_r + 1);
    printf("%d\n", zero_c + 1);

    return 0;
}
